/**
 * Local API Server for 00EVENTPULSE
 * Handles Ticketmaster API calls server-side to avoid exposing API keys in client
 * Also serves as a unified events API for all sources
 */

const http = require('http');
const https = require('https');
const axios = require('axios');
const { createClient } = require('@supabase/supabase-js');

const PORT = 8080;
const TICKETMASTER_API_KEY = process.env.TICKETMASTER_API_KEY || 'EhTiMKFgAbcmFG8wUvOytWVS7oGEapiA';

// Supabase configuration
const SUPABASE_URL = process.env.SUPABASE_URL || 'https://bsllkpvkowwndhhxtlln.supabase.co';
const SUPABASE_SERVICE_ROLE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY || '';

// Create Supabase client (service role for server-side)
let supabase = null;
if (SUPABASE_URL && SUPABASE_SERVICE_ROLE_KEY) {
  supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
  console.log('[api] Supabase client initialized');
} else {
  console.warn('[api] Supabase not configured - /supabase-events endpoint disabled');
}

/**
 * Canonical source registry
 * This defines the authoritative list of sources and their display names.
 * Keys are canonical source identifiers used in event.source field.
 * 
 * Naming convention: lowercase with hyphens (kebab-case)
 * - venue-based sources: kebab-case venue name (e.g., 'malmo-live', 'tele2-arena')
 * - aggregator sources: lowercase (e.g., 'ticketmaster')
 * - curated sources: lowercase (e.g., 'stockholm' for curated Stockholm events)
 */
const CANONICAL_SOURCES = {
  'ticketmaster': {
    label: 'Ticketmaster',
    type: 'aggregator',
  },
  'stockholm': {
    label: 'Stockholm',
    type: 'curated',
  },
  'kulturhuset': {
    label: 'Kulturhuset',
    type: 'venue',
  },
  'kulturhuset-barn-ung': {
    label: 'Kulturhuset Barn & Ung',
    type: 'venue',
  },
  'malmo-live': {
    label: 'Malmö Live',
    type: 'venue',
  },
  'debaser': {
    label: 'Debaser',
    type: 'venue',
  },
  'tele2-arena': {
    label: 'Tele2 Arena',
    type: 'venue',
  },
  'friends-arena': {
    label: 'Friends Arena',
    type: 'venue',
  },
  'avicii-arena': {
    label: 'Avicii Arena',
    type: 'venue',
  },
  'fotografiska': {
    label: 'Fotografiska',
    type: 'venue',
  },
  'berwaldhallen': {
    label: 'Berwaldhallen',
    type: 'venue',
  },
  'malmo-opera': {
    label: 'Malmö Opera',
    type: 'venue',
  },
  'sodra-teatern': {
    label: 'Södra Teatern',
    type: 'venue',
  },
  'annexet': {
    label: 'Annexet',
    type: 'venue',
  },
  'slakthuset': {
    label: 'Slakthuset',
    type: 'venue',
  },
  'fryshuset': {
    label: 'Fryshuset',
    type: 'venue',
  },
  'eventpulse': {
    label: 'EventPulse',
    type: 'aggregator',
  },
};

/**
 * Normalize source value to canonical key
 * Maps legacy/variant names to canonical keys
 */
const SOURCE_ALIAS_MAP = {
  // Legacy variations
  'malmolive': 'malmo-live',
  'stockholmlive': 'malmo-live',
};

/**
 * Get canonical source key
 * @param {string} source - Source value from event
 * @returns {string} Canonical source key
 */
function normalizeSource(source) {
  if (!source) return 'unknown';
  const normalized = source.toLowerCase().trim();
  return SOURCE_ALIAS_MAP[normalized] || normalized;
}

/**
 * Get source metadata for frontend dropdown
 * @returns {Array} Array of { key, label, type } objects
 */
function getSourcesMetadata() {
  return Object.entries(CANONICAL_SOURCES).map(([key, meta]) => ({
    key,
    label: meta.label,
    type: meta.type,
  }));
}

/**
 * Normalize event source to canonical key
 * @param {Object} event - Event object
 * @returns {Object} Event with normalized source
 */
function normalizeEvent(event) {
  return {
    ...event,
    source: normalizeSource(event.source),
  };
}

/**
 * Proxy Ticketmaster API requests
 */
async function fetchTicketmasterEvents(city = 'Stockholm', countryCode = 'SE', size = 50) {
  const url = `https://app.ticketmaster.com/discovery/v2/events.json?apikey=${TICKETMASTER_API_KEY}&city=${city}&countryCode=${countryCode}&size=${size}&sort=date,asc`;

  console.log(`[api] Fetching Ticketmaster events for ${city}...`);

  try {
    const response = await axios.get(url, { timeout: 15000 });

    if (response.status !== 200) {
      console.log(`[api] Ticketmaster returned ${response.status}`);
      return { error: `HTTP ${response.status}`, events: [] };
    }

    const data = response.data;

    if (!data._embedded || !data._embedded.events) {
      console.log(`[api] No events found`);
      return { events: [], count: 0 };
    }

    const events = data._embedded.events.map(ev => ({
      id: ev.id,
      title: ev.name,
      date: ev.dates?.start?.localDate || '',
      time: ev.dates?.start?.localTime ? ev.dates.start.localTime.substring(0, 5) : '',
      venue: ev._embedded?.venues?.[0]?.name || 'Unknown',
      area: ev._embedded?.venues?.[0]?.city?.name || city,
      description: ev.info || ev.pleaseNote || '',
      url: ev.url || '',
      source: 'ticketmaster',
      imageUrl: ev.images?.[0]?.url || null,
      priceRanges: ev.priceRanges || [],
    }));

    console.log(`[api] Ticketmaster: ${events.length} events`);
    return { events, count: events.length };
  } catch (error) {
    console.error(`[api] Ticketmaster error: ${error.message}`);
    return { error: error.message, events: [] };
  }
}

/**
 * Fetch from other sources directly (they don't need API keys)
 */
async function fetchOtherSources() {
  const results = { sources: {} };

  // Kulturhuset Elasticsearch
  try {
    const esResp = await axios.post(
      'https://elastic.kulturhusetstadsteatern.se/khst-events/_search',
      {
        size: 20,
        query: { bool: { must: [{ range: { tixStartDate: { gte: 'now' } } }] } },
        sort: [{ tixStartDate: { order: 'asc' } }],
      },
      { timeout: 10000, headers: { 'Content-Type': 'application/json' } }
    );

    if (esResp.data?.hits?.hits) {
      results.sources.kulturhuset = esResp.data.hits.hits.map(h => ({
        id: h._id,
        title: h._source?.drupalTitle || h._source?.tixName || 'Untitled',
        date: (h._source?.tixStartDate || '').split('T')[0],
        source: 'kulturhuset',
      }));
    }
  } catch (e) {
    console.log(`[api] Kulturhuset: ${e.message}`);
  }

  // Malmö Live API
  try {
    const malmoResp = await axios.get('https://malmolive.se/api/events', { timeout: 10000 });
    if (Array.isArray(malmoResp.data)) {
      results.sources.malmolive = malmoResp.data.slice(0, 20).map(e => ({
        id: e.tessitura_event_id || e.id,
        title: e.title || e.name || 'Untitled',
        date: (e.field_date_time || '').split('T')[0],
        source: 'malmolive',
      }));
    }
  } catch (e) {
    console.log(`[api] Malmö Live: ${e.message}`);
  }

  return results;
}

/**
 * Unified /events endpoint
 */
async function handleEvents(req, res) {
  const url = new URL(req.url, `http://localhost:${PORT}`);
  const city = url.searchParams.get('city') || 'Stockholm';
  const size = parseInt(url.searchParams.get('size') || '50');

  const ticketmaster = await fetchTicketmasterEvents(city, 'SE', size);
  const otherSources = await fetchOtherSources();

  // Normalize all event sources to canonical keys
  const normalizedTicketmaster = {
    ...ticketmaster,
    events: ticketmaster.events.map(normalizeEvent),
  };

  const normalizedOtherSources = {
    sources: {},
  };

  // Normalize Kulturhuset events
  if (otherSources.sources.kulturhuset) {
    normalizedOtherSources.sources.kulturhuset = otherSources.sources.kulturhuset.map(normalizeEvent);
  }

  // Normalize Malmö Live events (will become 'malmo-live' after normalization)
  if (otherSources.sources.malmolive) {
    normalizedOtherSources.sources.malmolive = otherSources.sources.malmolive.map(normalizeEvent);
  }

  // Collect all available sources (for frontend dropdown)
  const availableSources = new Set();
  normalizedTicketmaster.events.forEach(e => availableSources.add(e.source));
  Object.values(normalizedOtherSources.sources).forEach(events => {
    events.forEach(e => availableSources.add(e.source));
  });

  // Build sources metadata for dropdown (only include sources that have events)
  const sources = getSourcesMetadata().filter(s => availableSources.has(s.key));

  const response = {
    timestamp: new Date().toISOString(),
    ticketmaster: normalizedTicketmaster,
    otherSources: normalizedOtherSources,
    sources: sources,
    totalEvents: ticketmaster.count + 
      (otherSources.sources.kulturhuset?.length || 0) +
      (otherSources.sources.malmolive?.length || 0),
  };

  res.writeHead(200, { 
    'Content-Type': 'application/json',
    'Access-Control-Allow-Origin': '*',
  });
  res.end(JSON.stringify(response, null, 2));
}

/**
 * Health check endpoint with ingestion status
 */
async function handleHealth(req, res) {
  let ingestionStatus = null;

  if (supabase) {
    try {
      // Get latest ingestion run
      const { data: latestRun } = await supabase
        .from('ingestion_logs')
        .select('source, action, timestamp')
        .order('timestamp', { ascending: false })
        .limit(10);

      // Get events in last 24h
      const last24h = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();
      const { count: events24h } = await supabase
        .from('events')
        .select('id', { count: 'exact', head: true })
        .eq('status', 'published')
        .gte('start_time', last24h);

      // Get active sources
      const now = new Date().toISOString();
      const { data: activeSources } = await supabase
        .from('events')
        .select('source')
        .eq('status', 'published')
        .gte('start_time', now);

      const uniqueSources = [...new Set((activeSources || []).map(e => e.source))];

      ingestionStatus = {
        supabase: 'connected',
        last_ingestion_run: latestRun?.[0]?.timestamp || null,
        events_last_24h: events24h || 0,
        active_sources: uniqueSources,
        active_sources_count: uniqueSources.length,
        latest_runs: latestRun?.slice(0, 5).map(l => ({
          source: l.source,
          action: l.action,
          timestamp: l.timestamp
        })) || []
      };
    } catch (err) {
      ingestionStatus = {
        supabase: 'connected',
        error: 'Could not fetch ingestion stats: ' + err.message
      };
    }
  } else {
    ingestionStatus = {
      supabase: 'disconnected'
    };
  }

  res.writeHead(200, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    ticketmasterKey: TICKETMASTER_API_KEY ? 'configured' : 'missing',
    ingestion: ingestionStatus
  }));
}

/**
 * Fetch events from Supabase (normalized and stored events)
 * 
 * This is the PRIMARY endpoint for frontend.
 * Returns normalized events with metadata about data source.
 */
async function handleSupabaseEvents(req, res) {
  if (!supabase) {
    res.writeHead(503, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ 
      error: 'Supabase not configured',
      data_source: 'none',
      fallback_used: false
    }));
    return;
  }

  const url = new URL(req.url, `http://localhost:${PORT}`);
  const city = url.searchParams.get('city') || 'Stockholm';
  const days = parseInt(url.searchParams.get('days') || '365');
  const limit = parseInt(url.searchParams.get('limit') || '100');
  const source = url.searchParams.get('source') || null;

  try {
    // Calculate date range
    const now = new Date();
    const startDate = now.toISOString();
    const endDate = new Date(now.getTime() + days * 24 * 60 * 60 * 1000).toISOString();
    const last24h = new Date(now.getTime() - 24 * 60 * 60 * 1000).toISOString();

    // Get ingestion stats from ingestion_logs
    let ingestionStats = null;
    try {
      const { data: logs } = await supabase
        .from('ingestion_logs')
        .select('source, action, timestamp')
        .gte('timestamp', last24h)
        .order('timestamp', { ascending: false });

      if (logs) {
        const bySource = {};
        logs.forEach(log => {
          if (!bySource[log.source]) {
            bySource[log.source] = { inserted: 0, updated: 0 };
          }
          bySource[log.source][log.action]++;
        });

        ingestionStats = {
          events_last_24h: logs.length,
          by_source: bySource,
          last_run: logs[0]?.timestamp || null
        };
      }
    } catch (ingestErr) {
      console.warn('[api] Could not fetch ingestion stats:', ingestErr.message);
    }

    // Get total count of published events
    const { count: totalCount } = await supabase
      .from('events')
      .select('id', { count: 'exact', head: true })
      .eq('status', 'published');

    // Get active sources (sources with events)
    const { data: activeSourcesData } = await supabase
      .from('events')
      .select('source')
      .eq('status', 'published')
      .gte('start_time', startDate);

    const activeSourceKeys = [...new Set((activeSourcesData || []).map(e => e.source))];

    // Build query
    let query = supabase
      .from('events')
      .select(`
        id,
        title_en,
        title_sv,
        description_en,
        description_sv,
        start_time,
        end_time,
        source,
        venue_id,
        venues:venue_id(name, address),
        category_slug,
        is_free,
        price_min_sek,
        price_max_sek,
        ticket_url,
        image_url
      `)
      .gte('start_time', startDate)
      .lte('start_time', endDate)
      .eq('status', 'published')
      .order('start_time', { ascending: true })
      .limit(limit);

    // Filter by source if specified
    if (source) {
      query = query.eq('source', source);
    }

    const { data: events, error } = await query;

    if (error) {
      console.error('[api] Supabase query error:', error);
      res.writeHead(500, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ 
        error: error.message,
        data_source: 'supabase',
        fallback_used: false
      }));
      return;
    }

    // Transform to frontend format (UNIFIED EVENT SHAPE)
    const transformedEvents = (events || []).map(ev => ({
      id: ev.id,
      title: ev.title_en || ev.title_sv || 'Untitled',
      date: ev.start_time ? ev.start_time.split('T')[0] : '',
      time: ev.start_time ? ev.start_time.split('T')[1]?.substring(0, 5) : '',
      venue_name: ev.venues?.name || '',
      venue_address: ev.venues?.address || '',
      city: city,
      description: ev.description_en || ev.description_sv || '',
      source: ev.source, // Already canonical from ingestion
      category_slug: ev.category_slug || 'community',
      is_free: ev.is_free || false,
      price_min: ev.price_min_sek,
      price_max: ev.price_max_sek,
      ticket_url: ev.ticket_url || '',
      image_url: ev.image_url || null,
      // Legacy aliases for backwards compatibility
      venue: ev.venues?.name || '',
      area: city,
      url: ev.ticket_url || '',
      category: ev.category_slug || 'culture',
      isFree: ev.is_free || false,
      priceMin: ev.price_min_sek,
      priceMax: ev.price_max_sek,
      imageUrl: ev.image_url,
    }));

    // Sources for dropdown - ONLY from actual data in Supabase
    const sources = activeSourceKeys
      .filter(key => CANONICAL_SOURCES[key]) // Only known canonical sources
      .map(key => ({
        key,
        label: CANONICAL_SOURCES[key].label,
        type: CANONICAL_SOURCES[key].type
      }));

    const response = {
      // Metadata
      data_source: 'supabase',
      fallback_used: false,
      timestamp: new Date().toISOString(),

      // Ingestion info
      ingestion_stats: ingestionStats,
      total_published_events: totalCount || 0,
      active_sources_count: activeSourceKeys.length,

      // Event data
      events: transformedEvents,
      sources: sources,
      count: transformedEvents.length,

      // Query params used
      query_params: {
        city,
        days,
        limit,
        source
      }
    };

    res.writeHead(200, {
      'Content-Type': 'application/json',
      'Access-Control-Allow-Origin': '*',
    });
    res.end(JSON.stringify(response));
  } catch (err) {
    console.error('[api] Supabase fetch error:', err);
    res.writeHead(500, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ 
      error: err.message,
      data_source: 'supabase',
      fallback_used: false
    }));
  }
}

/**
 * Static events endpoint (for testing without API key)
 */
async function handleStaticEvents(req, res) {
  const events = [
    { id: '1', title: 'Test Event 1', date: '2026-03-27', venue: 'Test Venue', source: 'test' },
    { id: '2', title: 'Test Event 2', date: '2026-03-28', venue: 'Test Venue 2', source: 'test' },
  ];

  res.writeHead(200, { 
    'Content-Type': 'application/json',
    'Access-Control-Allow-Origin': '*',
  });
  res.end(JSON.stringify({ events, count: events.length }));
}

/**
 * Main server
 */
const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, `http://localhost:${PORT}`);

  console.log(`[${new Date().toISOString()}] ${req.method} ${url.pathname}`);

  if (url.pathname === '/health') {
    await handleHealth(req, res);
  } else if (url.pathname === '/debug-direct-events') {
    // DEPRECATED: Direct provider API access - for debugging only!
    console.warn('[api] WARNING: Using deprecated /debug-direct-events endpoint');
    await handleEvents(req, res);
  } else if (url.pathname === '/events') {
    // Redirect to debug endpoint with warning header
    res.writeHead(301, { 
      'Location': '/debug-direct-events',
      'Warning': '299 - "Deprecated: Use /supabase-events for production"',
      'Access-Control-Allow-Origin': '*',
    });
    res.end();
  } else if (url.pathname === '/events/static') {
    await handleStaticEvents(req, res);
  } else if (url.pathname === '/supabase-events') {
    await handleSupabaseEvents(req, res);
  } else {
    res.writeHead(200, { 'Content-Type': 'text/html' });
    res.end(`
<!DOCTYPE html>
<html>
<head><title>EventPulse API</title></head>
<body>
<h1>EventPulse API Server</h1>
<p>Endpoints:</p>
<ul>
  <li><a href="/health">/health</a> - Health check</li>
  <li><a href="/supabase-events">/supabase-events</a> - <strong>PRIMARY</strong>: Fetch normalized events from Supabase</li>
  <li><a href="/debug-direct-events">/debug-direct-events</a> - <em>DEPRECATED</em>: Direct provider API (debug only)</li>
  <li><a href="/events/static">/events/static</a> - Static test events</li>
</ul>
</body>
</html>
    `);
  }
});

server.listen(PORT, () => {
  console.log(`
╔════════════════════════════════════════════╗
║     EventPulse API Server                  ║
╠════════════════════════════════════════════╣
║  Server running at http://localhost:${PORT}  ║
║  Ticketmaster API: ${TICKETMASTER_API_KEY ? 'configured' : 'MISSING'}           ║
║  Supabase: ${supabase ? 'connected' : 'disabled'}                       ║
║  Press Ctrl+C to stop                      ║
╚════════════════════════════════════════════╝
`);
});

